<#
  baixar-imagens-externas.ps1 — baixa os desenhos técnicos que o site atual da LSQ carrega de outros
  servidores (songqiao.com e lsq-coupling.ru). Rode na mesma máquina em que rodou baixar-site-lsq.ps1.
  Uso: powershell -ExecutionPolicy Bypass -File .\baixar-imagens-externas.ps1
  Resultado: lsq-imagens-externas.zip na Área de Trabalho. Envie esse zip.
#>
$ErrorActionPreference = 'Continue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$ProgressPreference = 'SilentlyContinue'
$UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126 Safari/537.36'
$Root = Join-Path ([Environment]::GetFolderPath('Desktop')) 'lsq-imagens-externas'
New-Item -ItemType Directory -Force -Path $Root | Out-Null
$Log = Join-Path $Root 'log.txt'
'' | Set-Content $Log

