$n = 0
foreach ($it in $items) {
  $n++
  $slug = $it[0]; $url = $it[1]
  $dir = Join-Path $Root $slug
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  $name = 'ext_' + [IO.Path]::GetFileName(($url -split '\?')[0])
  $dest = Join-Path $dir $name
  if (Test-Path $dest) { continue }
  Write-Host ("[{0}/{1}] {2}" -f $n, $items.Count, $name)
  try {
    Invoke-WebRequest -Uri $url -OutFile $dest -UserAgent $UA -UseBasicParsing -TimeoutSec 60 -Headers @{ Referer = 'https://lsq-coupling.com.br/' }
    Start-Sleep -Milliseconds 200
  } catch {
    Add-Content $Log "FALHOU $url -> $($_.Exception.Message)"
  }
}
$zip = Join-Path ([Environment]::GetFolderPath('Desktop')) 'lsq-imagens-externas.zip'
if (Test-Path $zip) { Remove-Item $zip }
Compress-Archive -Path (Join-Path $Root '*') -DestinationPath $zip
Write-Host ""
Write-Host "Pronto: $zip"
